import json
from pathlib import Path

projects=[]
def add(id,name,cat,status,kind,tag,audience,problem,features,story,stack,url='',note='',color='blue'):
    def pair(s):
        a,b=s.split(' || ');return {'fr':a,'en':b}
    projects.append(dict(id=id,name=name,category=cat,status=status,kind=pair(kind),tag=pair(tag),audience=pair(audience),problem=pair(problem),features=[pair(f) for f in features],story=pair(story),stack=stack,url=url,note=pair(note) if note else {'fr':'','en':''},color=color))

add('excel2airtable','Excel2Airtable','business','service','Service sur mesure || Bespoke service','Vos fichiers Excel deviennent un système de travail clair. || Turn your Excel files into a clear working system.','TPE, PME, consultants et équipes administratives. || Small businesses, consultants and administrative teams.','Des fichiers dispersés, des doublons et des suivis manuels rendent le travail difficile à partager. || Scattered files, duplicates and manual tracking make teamwork harder.', ['Migration et organisation des données || Data migration and organization','Tables reliées et vues adaptées à votre activité || Linked tables and views tailored to your business','Interfaces par rôle et automatisations selon le besoin || Role-based interfaces and automations as needed','Livraison dans votre espace Airtable || Delivery in your own Airtable workspace'], 'Mon expérience administrative m’a appris qu’un bon outil commence par un processus clair. Excel2Airtable transforme cette approche en une prestation concrète. || My administrative experience taught me that a good tool starts with a clear process. Excel2Airtable turns that approach into a practical service.', ['Airtable','Make','Excel'],note='Prestation disponible. Le périmètre se définit avec vous ; vous restez propriétaire de votre base, de vos données et de votre abonnement. || Service available. We define the scope together; you own your base, data and subscription.',color='orange')
add('dictaday','DictaDay','daily','test','Assistant vocal || Voice assistant','Videz votre tête le soir. Retrouvez votre plan le matin. || Clear your head at night. Find your plan in the morning.','Personnes actives et indépendants qui préfèrent dicter leurs tâches. || Busy people and freelancers who prefer to dictate tasks.','Les idées et les tâches s’accumulent au mauvais moment, sans endroit simple où les déposer. || Ideas and tasks pile up at inconvenient moments, with no simple place to capture them.', ['Capture de notes vocales sur Telegram || Voice-note capture on Telegram','Transcription et classement des tâches || Task transcription and categorization','Récapitulatif et plan d’action matinal || Morning recap and action plan','Suivi des tâches confirmées, reportées ou archivées || Tracking confirmed, postponed or archived tasks'], 'Je voulais vider ma tête le soir sans ouvrir un gestionnaire de tâches. C’est devenu « Vocal, Dodo, Planifié ». || I wanted to clear my head at night without opening a task manager. That became “Voice, Sleep, Planned”.',['Telegram','Make','OpenAI','Google Sheets','Email'],'https://www.dictaday.com', 'V1 fonctionnelle et multi-utilisateur. L’expérience continue à être améliorée, notamment la dictée et les scénarios d’automatisation. || Functional multi-user V1. The experience is still being improved, including dictation and automation workflows.',color='blue')
add('prospection360','Prospection360','business','test','Micro-SaaS de prospection || Lead generation micro-SaaS','Trouvez des prospects par niche et par ville. || Find prospects by niche and city.','Indépendants et petites entreprises qui recherchent des prospects ciblés. || Freelancers and small businesses looking for targeted prospects.','Trouver des entreprises pertinentes dans une ville précise demande du temps, et les plateformes peuvent coûter cher. || Finding relevant businesses in a specific city takes time, and platforms can be expensive.', ['Recherche selon une niche précise || Search by a specific niche','Ciblage par ville ou localisation || Targeting by city or location','Résultats de prospects ciblés || Targeted business lead results','100 crédits gratuits au démarrage, 1 crédit par lead || 100 initial free credits, 1 credit per lead'], 'J’avais besoin de trouver des leads dans des niches et des villes précises, sans payer des sommes exorbitantes sur les plateformes. || I needed leads in specific niches and cities without paying excessive platform fees.', ['Lovable'],'https://prospection360.lovable.app/', 'MVP publié et prêt à tester. Après les crédits gratuits, un accès payant est prévu ; les modalités restent à préciser. || Published MVP ready to test. Paid access is planned after the free credits; details are still to be defined.',color='pink')
add('effipv','EffiPV','business','test','Automatisation documentaire || Document automation','Des notes de réunion à un procès-verbal structuré. || From meeting notes to structured minutes.','Équipes, associations et responsables qui rédigent des comptes rendus. || Teams, associations and managers who write meeting minutes.','Transformer des notes en un document lisible prend du temps après chaque réunion. || Turning notes into a readable document takes time after each meeting.', ['Collecte des informations via formulaire || Collect meeting information through a form','Génération d’un brouillon structuré || Generate a structured draft','Création du document dans Google Docs || Create the document in Google Docs','Transmission par email pour relecture et validation || Email delivery for review and approval'], 'Je connais le temps que prend la rédaction d’un procès-verbal. EffiPV part de notes et conserve une étape humaine de relecture et de validation. || I know how long meeting minutes take to write. EffiPV starts from notes and keeps a human review and approval step.', ['Tally','Make','OpenAI','Google Docs','Google Drive','Email'],'https://www.dictaday.com/effi-proces-verbaux', 'Workflow construit et testé sur ordinateur et mobile. Les documents générés sont des brouillons à relire et valider. || Workflow built and tested on desktop and mobile. Generated documents are drafts to review and approve.',color='blue')
add('follow2connect','Follow2Connect','business','test','Application de networking || Networking app','Une rencontre ne devrait pas se perdre dans votre téléphone. || A good connection should not get lost in your phone.','Professionnels qui rencontrent des contacts lors d’événements ou de sorties. || Professionals meeting contacts at events or while out.','On rencontre des personnes intéressantes, puis on oublie le contexte ou le bon moment pour les recontacter. || We meet interesting people, then forget the context or the right time to follow up.', ['Fiches contacts et contexte de rencontre || Contact records and meeting context','Date, notes et prochaine relance || Dates, notes and next follow-up','Tableau de bord des contacts à recontacter || Dashboard of contacts to follow up with','Suivi du statut « Contacté OK » || “Contacted OK” status tracking'], 'L’idée est née de mes rencontres professionnelles : garder une trace utile et donner une suite aux échanges. || The idea grew from my professional encounters: keep useful context and follow through on conversations.', ['Replit'],'https://follow2connect.replit.app/', 'Application toujours testable, gratuite actuellement. || App still available to test, currently free.',color='orange')
add('solomaiscarre','SoloMaisCarré','business','test','Tableau de bord pour indépendants || Freelancer dashboard','Indépendant, avec vos obligations et documents sous contrôle. || Independent, with your obligations and documents under control.','Freelances et solopreneurs, notamment en France. || Freelancers and solopreneurs, especially in France.','Les échéances, frais professionnels et documents se dispersent entre plusieurs outils. || Deadlines, business expenses and documents get scattered across different tools.', ['Suivi des obligations et échéances administratives || Track administrative obligations and deadlines','Organisation des frais professionnels || Organize business expenses','Espace de dépôt et rangement des documents || Document upload and organization space','Suivi des formations et du développement personnel || Track training and personal development'], 'Un besoin très concret d’indépendante : réunir les rappels administratifs et les informations de son activité dans un seul espace. || A practical freelancer need: bring administrative reminders and business information into one place.', ['Replit'],'https://solomaiscarre-dashboard.replit.app/', 'Tableau de bord accessible. Le problème de sauvegarde des données après déconnexion a été résolu. || Dashboard available. The data persistence issue after logout has been resolved.',color='blue')
add('nia','NIA','business','build','Partenaire IA commercial || AI business partner','Une base structurée pour suivre vos opportunités commerciales. || A structured base for tracking business opportunities.','Mon activité, avec une approche pouvant inspirer un système commercial sur mesure. || My business, with an approach that can inspire a bespoke sales system.','Les opportunités arrivent par plusieurs canaux et les relances deviennent difficiles à suivre. || Opportunities arrive through different channels and follow-ups become difficult to track.', ['Opportunités et prospects reliés || Linked opportunities and prospects','Actions, relances et catalogue d’offres || Actions, follow-ups and offer catalog','Sources et journal de suivi NIA || Sources and NIA activity log','Champs de validation humaine || Human approval fields'], 'Pendant que je construis mes projets, je veux mieux repérer et suivre les opportunités. NIA est née pour soutenir ce développement commercial. || While I build my projects, I want to spot and track opportunities better. NIA was created to support that business development.', ['Airtable'],note='Base Airtable créée : 6 tables et 68 champs. Les automatisations et l’intelligence de l’agent restent à configurer ; la veille automatique n’est pas active. || Airtable base created: 6 tables and 68 fields. Agent intelligence and automations still need configuration; automatic monitoring is not active.',color='pink')
add('effivoeux','EffiVœux','business','test','Automatisation d’envois || Message automation','Des envois personnalisés, avec un suivi propre. || Personalized messages with clear tracking.','Entreprises, associations et équipes qui envoient vœux ou invitations. || Businesses, associations and teams sending greetings or invitations.','Personnaliser et suivre des envois répétitifs prend du temps et favorise les oublis. || Personalizing and tracking repetitive messages takes time and makes omissions more likely.', ['Messages personnalisés depuis une liste de contacts || Personalized messages from a contact list','Envoi de pièces jointes || Attachment delivery','Mise à jour du statut « Contacté » || “Contacted” status updates','Usage pour vœux et invitations || Use for greetings and invitations'], 'Envoyer des cartes de vœux ou des invitations sans répéter les mêmes gestes, tout en gardant une personnalisation. || Send greetings or invitations without repeating the same steps, while keeping messages personal.', ['Google Sheets','Gmail','Make / Apps Script'],note='Automatisation fonctionnelle. La commercialisation comme offre autonome reste à définir. || Functional automation. Packaging it as a standalone offer is still to be defined.',color='orange')
add('effimetiers','EffiMétiers','business','build','Mini-apps pour artisans || Mini-apps for tradespeople','Un suivi simple, adapté au métier et au chantier. || Simple tracking tailored to the trade and the job.','Artisans, avec un premier focus sur la rénovation. || Tradespeople, with an initial focus on renovation.','Suivre clients, photos et avancement d’un chantier avec des outils dispersés complique le quotidien. || Tracking customers, photos and job progress across scattered tools complicates everyday work.', ['Fiches clients et chantiers || Customer and job records','Photos avant et après || Before-and-after photos','Historique et suivi opérationnel || History and operational tracking','Première déclinaison : EffiRénovation || First version: EffiRénovation'], 'Les artisans veulent retrouver rapidement l’essentiel de leurs chantiers. L’idée est de construire un outil simple pour chaque métier. || Tradespeople want quick access to essential job information. The idea is to build a simple tool for each trade.', ['Airtable','Make'],'https://www.dictaday.com/effi-metiers', 'Univers et prototypes préparés. EffiRénovation est le premier cas d’usage à tester sur le terrain. || Product family and prototypes prepared. EffiRénovation is the first use case to test in the field.',color='orange')
add('coeursunis','CœursUnis · LeCarnetMariage','business','build','Outil pour wedding planners || Wedding planner tool','Tous les éléments d’un mariage au même endroit. || Every part of a wedding in one place.','Wedding planners, avec un focus envisagé sur l’Afrique francophone. || Wedding planners, with a proposed focus on French-speaking Africa.','Des mariages suivis dans Excel avec « mille onglets » deviennent difficiles à coordonner. || Weddings tracked in Excel with “a thousand tabs” become difficult to coordinate.', ['Clients et dossiers de mariage || Clients and wedding records','Invités et RSVP || Guests and RSVPs','Prestataires, lieux et budget || Vendors, venues and budgets','Tâches et suivi de l’organisation || Tasks and planning follow-up'], 'Une wedding planner gérait encore ses mariages avec Excel et une multitude d’onglets. J’ai voulu réunir l’organisation dans un système plus lisible. || A wedding planner was managing weddings in Excel with countless tabs. I wanted to bring planning into a clearer system.', ['Airtable Interfaces','Make'],note='MVP Airtable travaillé. La cible professionnelle et le périmètre final restent à stabiliser. || Airtable MVP developed. The professional audience and final scope are still being refined.',color='pink')
add('batlas','BAtlas · Business Atlas','business','test','Plateforme économique locale || Local business platform','Les acteurs et opportunités d’une ville deviennent visibles. || Make a city’s businesses and opportunities visible.','Acteurs économiques locaux, habitants, entreprises et collectivités. || Local businesses, residents and municipalities.','Les informations économiques locales sont dispersées entre sites, réseaux et institutions. || Local business information is scattered across websites, networks and institutions.', ['Annuaire d’acteurs locaux || Directory of local businesses','Événements et actualités || Events and news','Opportunités locales || Local opportunities','Rubriques stages et alternance || Internship and apprenticeship sections'], 'Rendre l’information économique locale plus facile à trouver. Sannois Business Atlas est le premier prototype de cette approche. || Make local business information easier to find. Sannois Business Atlas is the first prototype of this approach.', ['Lovable','GitHub','Vercel'],'https://sannois-business-atlas.vercel.app/', 'Prototype en ligne. Une adaptation pour d’autres communes est une piste à développer. || Online prototype. Adaptation for other municipalities is a possible next step.',color='blue')
add('60before9','60Before9','daily','test','Application mobile Android || Android mobile app','Marchez avant de scroller. Reprenez votre matinée. || Walk before you scroll. Reclaim your morning.','Personnes qui veulent retrouver une routine de marche matinale. || People who want to restore a morning walking routine.','Une heure de scrolling au réveil peut remplacer le temps que l’on voulait consacrer à soi. || An hour of scrolling after waking can replace the time we wanted for ourselves.', ['Défi : 60 minutes de marche avant 9 h || Challenge: a 60-minute walk before 9 AM','Suivi du temps et du mouvement par capteurs || Time and movement tracking through sensors','Validation du défi matinal || Morning challenge validation','Blocage et déblocage des apps : objectif en cours de fiabilisation || App blocking and unlocking: goal still being made reliable'], 'Je marchais une heure chaque matin, puis le scrolling a pris cette place. 60Before9 change l’ordre : d’abord la marche, ensuite les réseaux. || I used to walk an hour each morning, then scrolling took its place. 60Before9 changes the order: walk first, social apps afterwards.', ['Replit','React Native','Expo','Android','GitHub Actions'],note='APK interne en test. Les capteurs et le véritable blocage des applications restent à fiabiliser. Démonstration sur demande, sans téléchargement public. || Internal APK under testing. Sensors and actual app blocking still need reliability work. Demo on request; no public download.',color='orange')
add('carnet-voyage','Carnet de Voyage','daily','test','Application de récit de voyage || Travel storytelling app','Composez le récit de vos voyages, au fil des étapes. || Tell the story of your travels, step by step.','Voyageurs qui souhaitent conserver et partager leurs souvenirs. || Travelers who want to preserve and share their memories.','Photos, étapes et anecdotes restent éparpillées et le récit du voyage se perd. || Photos, trip stages and anecdotes get scattered and the travel story gets lost.', ['Bibliothèque de plusieurs carnets || Library of travel journals','Destination, dates et couverture || Destination, dates and cover','Journal avec textes, photos et étapes || Journal with text, photos and trip stages','Aperçu du récit et lien de partage || Story overview and sharing link'], 'Mon carnet AfriQuest25 a commencé dans Notion. Je l’ai transformé en application Lovable pour composer et partager mes récits plus simplement. || My AfriQuest25 journal started in Notion. I turned it into a Lovable app to compose and share my stories more simply.', ['Lovable'],'https://carnet-de-vacances.lovable.app/', 'Application toujours testable, gratuite pour le moment. || App still available to test, currently free.',color='pink')
add('pontenfant','PontEnfant','family','concept','Application familiale envisagée || Planned family app','Les informations des enfants circulent plus sereinement. || Help children’s information flow more calmly.','Parents séparés qui souhaitent organiser les informations de leurs enfants. || Separated parents who want to organize information about their children.','Partager les informations importantes peut devenir difficile lorsque les échanges directs sont compliqués. || Sharing important information can become difficult when direct communication is strained.', ['Espace d’informations par enfant || Information space for each child','École, santé et activités || School, health and activities','Documents et mises à jour || Documents and updates','Vacances et organisation familiale || Holidays and family organization'], 'Aider les parents séparés à faire circuler l’essentiel concernant leurs enfants, sans dépendre d’échanges directs. || Help separated parents share essential information about their children without relying on direct exchanges.', ['Stack à définir / To be defined'],note='Concept et expérience utilisateur structurés. Aucun produit public disponible à ce stade ; sécurité et confidentialité font partie du cadrage. || Concept and user experience outlined. No public product at this stage; security and privacy are part of scoping.',color='blue')
add('ton-epoque','Fais-moi vivre ton époque','family','concept','Programme familial digital envisagé || Planned digital family program','Les souvenirs d’une génération deviennent un héritage partagé. || Turn a generation’s memories into a shared legacy.','Familles et enfants adultes qui veulent préserver les souvenirs de leurs aînés. || Families and adult children wanting to preserve older relatives’ memories.','Les souvenirs risquent de disparaître lorsqu’on ne prend pas le temps de les recueillir. || Memories can disappear when we do not take the time to collect them.', ['Programme de questions sur 12 semaines envisagé || Planned 12-week question program','Réponses du senior en texte ou audio || Older relative’s text or audio answers','Lecture et échanges avec la famille || Reading and discussion with family','Conservation des récits familiaux || Preservation of family stories'], 'Donner aux aînés un espace pour raconter leur époque et aux familles une façon de garder cette mémoire. || Give older relatives a place to tell the story of their time and families a way to keep those memories.', ['Stack à définir / To be defined'],note='Concept à valider. Le format et l’expérience pour les seniors restent à concevoir. || Concept to validate. The format and older adults’ experience still need design.',color='pink')
add('zero-tracas','Zéro Tracas Gestion Admin','business','concept','Assistant administratif IA envisagé || Planned AI admin assistant','Dictez une tâche. Retrouvez-la au bon endroit. || Dictate a task. Find it in the right place.','Assistantes administratives, notamment en Afrique francophone. || Administrative assistants, particularly in French-speaking Africa.','Les tâches se dispersent entre carnets, WhatsApp et mémoire, ce qui complique le suivi. || Tasks get scattered across notebooks, WhatsApp and memory, making tracking difficult.', ['Saisie écrite ou vocale sur Telegram envisagée || Planned written or voice input on Telegram','Classement des tâches par IA || AI task categorization','Centralisation dans Airtable || Centralization in Airtable','Organisation du suivi administratif || Administrative follow-up organization'], 'Les assistantes gèrent une multitude de demandes. Je veux leur permettre de les capturer simplement et de les retrouver dans un système organisé. || Assistants handle many requests. I want them to capture those requests easily and find them in an organized system.', ['Telegram','IA / AI','Airtable','Make'],note='Concept. Le besoin terrain et le périmètre doivent être validés avant construction. || Concept. Field demand and scope need validation before building.',color='orange')
add('entrenous','EntreNous.Point','community','concept','Application de facilitation envisagée || Planned facilitation app','Un espace pour répondre franchement, sans se dévoiler. || A space to answer honestly without revealing yourself.','Animateurs d’ateliers, formateurs, équipes et associations. || Workshop facilitators, trainers, teams and associations.','La pression du groupe peut empêcher certaines personnes de s’exprimer honnêtement. || Group pressure can prevent people from expressing themselves honestly.', ['Sessions accessibles par lien unique envisagées || Planned sessions accessible through a unique link','Réponses sous alias || Responses under an alias','Résultats collectifs en direct || Live collective results','Données éphémères et suppression à concevoir || Ephemeral data and deletion to be designed'], 'Créer un espace de parole où l’on peut répondre honnêtement sans subir la pression d’un groupe. || Create a space where people can answer honestly without group pressure.', ['Web app envisagée / Planned web app'],note='Concept cadré, pas encore construit. Confidentialité, modération et suppression des données doivent être mises en œuvre. || Outlined concept, not yet built. Privacy, moderation and data deletion still need implementation.',color='blue')
add('assistpro','AssistPro Africa · Le Cercle','community','live','Communauté d’entraide || Peer community','Mieux organiser son travail, ensemble. || Organize work better, together.','Assistantes administratives africaines déjà en poste, et toute personne souhaitant mieux organiser son travail. || Administrative assistants already working in Africa, and anyone wanting better work organization.','Les assistantes ont besoin d’échanger sur leurs pratiques et de trouver des ressources adaptées au quotidien. || Assistants need to exchange practical experience and find resources that fit daily work.', ['Annonces et actualités || Announcements and news','Bibliothèque de ressources || Resource library','Salon d’échanges entre assistantes || Discussion space for assistants','Démonstrations pratiques et partage de modèles || Practical demonstrations and template sharing'], 'Créer un espace accessible de partage et d’entraide pour les assistantes. WhatsApp facilite les échanges avec le public africain. || Create an accessible space for assistants to share and help each other. WhatsApp makes interaction easier for an African audience.', ['WhatsApp','Google Meet','Google Drive'],note='Communauté gratuite et opérationnelle. Première animation prévue le 12 octobre 2026. Pour rejoindre Le Cercle, contactez-moi sur WhatsApp. || Free, active community. First community activity planned for 12 October 2026. Contact me on WhatsApp to join.',color='pink')

add('mailbee','MailBee','business','operational','Assistante IA pour Gmail || AI assistant for Gmail','Les emails importants repérés. Les réponses déjà préparées. || Important emails identified. Replies already drafted.','Entrepreneurs, consultants, TPE et PME utilisant Gmail. || Entrepreneurs, consultants and small businesses using Gmail.','Les demandes importantes se perdent parmi les newsletters et promotions ; préparer chaque réponse prend du temps. || Important requests get lost among newsletters and promotions; preparing each reply takes time.', ['Analyse des nouveaux emails dans Gmail || Analysis of new emails in Gmail','Repérage des messages qui nécessitent une réponse || Identification of messages requiring a reply','Préparation de brouillons adaptés au contexte || Preparation of context-aware reply drafts','Relecture et envoi par l’utilisateur || User review and sending'], 'Le besoin est né du traitement de boîtes email génériques : retrouver les demandes importantes et préparer les réponses plus vite. Je l’utilise dans mon activité. || The need came from handling shared inboxes: find important requests and prepare replies faster. I use it in my own business.', ['Gmail','Make','OpenAI'],note='Automatisation fonctionnelle, utilisée au quotidien. Les erreurs techniques ont été résolues. MailBee prépare des brouillons ; vous gardez la validation et l’envoi. Démonstration sur demande. || Functional automation, used daily. Technical errors have been resolved. MailBee prepares drafts; you retain review and sending. Demo on request.',color='orange')
add('seniorcare','SeniorCare','business','demo','Automatisation de coordination || Coordination automation','Chaque intervention auprès d’un senior, suivie du début à la fin. || Every senior care visit tracked from start to finish.','Services d’aide à domicile, associations, CCAS et agences spécialisées. || Home-care services, nonprofits, local social services and specialist agencies.','Demandes, affectations et nouvelles aux proches circulent entre emails, appels et tableaux, avec des risques d’oubli. || Requests, assignments and family updates are scattered across emails, calls and spreadsheets, making omissions more likely.', ['Collecte des demandes et fiches bénéficiaires || Request collection and beneficiary records','Affectation des interventions et suivi dans Airtable || Visit assignment and tracking in Airtable','Confirmations, rappels et notifications aux proches || Confirmations, reminders and family notifications','Recueil de satisfaction et suivi de l’activité || Feedback collection and activity tracking'], 'D’abord nommé Move&Care, ce projet vise à simplifier la coordination des interventions et à tenir les proches informés, des courses aux rendez-vous médicaux. || Originally called Move&Care, this project simplifies visit coordination and keeps relatives informed, from errands to medical appointments.', ['Tally','Make','Airtable'],note='Solution construite et prête pour une démonstration sur demande. Le catalogue présente la solution ; l’accès à l’outil se fait lors de la démonstration. || Built solution ready for a demo on request. The catalog introduces the solution; access to the tool is provided during the demonstration.',color='blue')

# Update confirmed product maturity and tested functionality.
byid={p['id']:p for p in projects}
e=byid['entrenous']
e['status']='operational'
e['kind']={'fr':'Jeu interactif de groupe','en':'Interactive group game'}
e['tag']={'fr':'Le jeu interactif qui libère la parole.','en':'The interactive game that gets people talking.'}
e['audience']={'fr':'RH, entreprises, associations, animateurs de team building, séminaires et ateliers, ainsi que groupes d’amis.','en':'HR teams, businesses, associations, team-building facilitators, seminars, workshops and groups of friends.'}
e['problem']={'fr':'La pression du groupe peut freiner les réponses franches. Un jeu interactif facilite la participation et ouvre la discussion.','en':'Group pressure can hold back honest answers. An interactive game helps everyone participate and opens up discussion.'}
e['features']=[{'fr':'Questionnaire interactif depuis le téléphone','en':'Interactive questionnaire on each participant’s phone'},{'fr':'Réponses anonymes et résultats collectifs en direct','en':'Anonymous answers and live group results'},{'fr':'Tableau de bord pour animer les échanges','en':'Dashboard to facilitate discussion'},{'fr':'Effacement automatique des données de session à minuit','en':'Automatic deletion of session data at midnight'}]
e['stack']=['Application web / Web app']
e['note']={'fr':'Application construite, fonctionnelle et testée lors de deux événements. Les inscriptions recueillent des emails ; le volet RGPD reste à finaliser avant de développer la prospection auprès des RH et des organisateurs. Démonstration sur demande.','en':'Built, functional app tested at two events. Registration collects email addresses; GDPR work remains to be finalized before expanding outreach to HR teams and event organizers. Demo on request.'}
f=byid['effimetiers']
f['status']='test'
f['kind']={'fr':'Fidélisation et mémoire client pour artisans','en':'Customer retention and history for tradespeople'}
f['tag']={'fr':'Restez l’artisan auquel vos clients pensent en premier.','en':'Stay the first tradesperson your customers think of.'}
f['problem']={'fr':'Entre deux interventions, le client peut oublier son artisan et chercher ailleurs. Les informations, coûts, commentaires et photos doivent rester accessibles pour préparer la prochaine relance.','en':'Between visits, a customer may forget their tradesperson and look elsewhere. Information, costs, comments and photos need to stay accessible to prepare the next follow-up.'}
f['story']={'fr':'Après une intervention, l’artisan connaît le besoin à venir. EffiMétiers conserve son historique et lui rappelle de reprendre contact suffisamment tôt pour rester présent dans l’esprit du client.','en':'After a visit, the tradesperson knows what may be needed next. EffiMétiers keeps the history and reminds them to get back in touch early enough to stay on the customer’s mind.'}
f['example']={'fr':'Le 1er juillet, Jack tond la pelouse de Mme Machin. Il enregistre les photos avant/après, le coût et ses commentaires. Une nouvelle tonte serait souhaitable environ cinq semaines plus tard. L’outil lui rappelle le 22 juillet, après trois semaines, de reprendre contact : Jack relance lui-même Mme Machin, avant qu’elle ait besoin de chercher un autre artisan. Sa galerie lui sert aussi à montrer son travail à de futurs clients.','en':'On 1 July, Jack mows Mrs Machin’s lawn. He records before-and-after photos, the cost and his comments. Another mow would ideally be needed about five weeks later. On 22 July, after three weeks, the tool reminds him to get back in touch: Jack contacts Mrs Machin himself before she needs to look for someone else. His gallery also helps him show his work to prospective customers.'}

f['features']=[{'fr':'Fiche client complète et historique des interventions','en':'Complete customer record and visit history'},{'fr':'Coûts, commentaires et photos avant/après réunis','en':'Costs, comments and before-and-after photos in one place'},{'fr':'Rappel anticipé pour préparer la prochaine intervention','en':'Early reminder to prepare the next visit'},{'fr':'L’outil rappelle ; l’artisan contacte lui-même son client','en':'The tool sends a reminder; the tradesperson contacts the customer personally'},{'fr':'Galerie avant/après pour présenter son travail à de futurs clients','en':'Before-and-after gallery to show work to prospective customers'},{'fr':'EffiVerdure, EffiRénovations et EffiChauffage : trois déclinaisons métier','en':'EffiVerdure, EffiRénovations and EffiChauffage: three trade-specific versions'}]
f['audience']={'fr':'Artisans de la verdure, de la rénovation et du chauffage.','en':'Landscaping, renovation and heating tradespeople.'}
f['note']={'fr':'EffiVerdure, EffiRénovations et EffiChauffage sont prêts à être testés. EffiRénovation a déjà été testé par un artisan ; aucun retour détaillé n’a encore été recueilli.','en':'EffiVerdure, EffiRénovations and EffiChauffage are ready to test. EffiRénovation has already been tested by a tradesperson; detailed feedback has not yet been received.'}

